#include "dve/editor_prototype.hpp"
#include <iostream>
int main(int argc,char** argv){if(argc!=2){std::cerr<<"Usage: dve_create_prototype NEW_PROJECT_DIRECTORY\n";return 2;}try{auto doc=dve::editor::make_prototype_starter();auto materials=dve::editor::EditorMaterialLibrary::make_default();std::string error;if(!dve::editor::export_prototype_project(doc,materials,std::filesystem::absolute(argv[1]),&error)){std::cerr<<error<<'\n';return 1;}std::cout<<"Created first-person prototype: "<<argv[1]<<"\nRun dve_player with that directory, or open project.dveproject in the editor.\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
